function UICultivateEquipAndCoreGroupNode:InitEquipIdList(cardDojo)
    local isOwnEquip = false
    local equipIdList = {0, 0, 0, 0}
    local GetEquipIdKeyByPart = EquipUtils.GetEquipIdKeyByPart
    for i = 1, Constants.CardEquipmentNo do
        local key = GetEquipIdKeyByPart(i)
        local playerEquipId = checkNumber(cardDojo[key])
        if not isOwnEquip then
            isOwnEquip = playerEquipId > 0
        end
        --- equipment1 equipment2
        equipIdList[i] = playerEquipId
    end
    self:SetEquipIdList(equipIdList)
    return isOwnEquip
end

function UICultivateEquipAndCoreGroupNode:InitEquipPart2SuitId()
    self.equipPart2SuitId = {}
    local equipIdList = self:GetEquipIdList()
    for i = 1, Constants.CardEquipmentNo do
        local playerEquipId = checkNumber(equipIdList[i])
        if playerEquipId > 0 then
            local dojo  = equipComp:GetEquipById(playerEquipId)
            local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
            self.equipPart2SuitId[i] = equipVo.suitId
        end
    end
end

function UICultivateEquipAndCoreGroupNode:UpdateEquipPart2SuitId(dojo, part)
    if dojo then
        local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
        self.equipPart2SuitId[part] = equipVo.suitId
    else
        self.equipPart2SuitId[part] = nil
    end
end

function UICultivateEquipAndCoreGroupNode:CheckSuitIsActive(equipmentCoreDojo)
    local suitId, quality

    local isActive = equipmentCoreDojo ~= nil and next(equipmentCoreDojo) ~= nil
    if isActive then
        local refId = equipmentCoreDojo.equipmentCoreId
        ---@type EquipCoreVo
        local equipCoreVo = cardConfMgr:GetEquipCoreVoById(refId)
        suitId = equipCoreVo.suitId
        quality = equipCoreVo.quality

        local suitId2Count = {}
        for i, v in pairs(self.equipPart2SuitId) do
            local count = suitId2Count[v]
            suitId2Count[v] = count == nil and 1 or (count + 1)
        end

        local count = suitId2Count[suitId] or 0
        isActive = EquipUtils.CheckCoreIsUnLock(refId, count)
    end
   
    return isActive, suitId, quality
end

