function UICultivateEquipAndCoreGroupNode:RefreshUI(cardDojo)
    self:SetCardDojo(cardDojo)

    local isOwnEquip = self:InitEquipIdList(cardDojo)
    self:InitEquipPart2SuitId()
    
    local playerEquipmentCoreId = checkNumber(cardDojo.equipmentCore)
    self:SetPlayerEquipmentCoreId(playerEquipmentCoreId)

    local equipmentCoreDojo
    if playerEquipmentCoreId > 0 then
        equipmentCoreDojo = equipComp:GetEquipCoreById(playerEquipmentCoreId)
    end
    local activeCount = self:UpdateUI(equipmentCoreDojo, isOwnEquip)
    self:HandleCoreEffect(activeCount, true)

end

function UICultivateEquipAndCoreGroupNode:RefreshUIByCustomData(data)
    local equipIdList = data.equipIdList or {}
    self:SetEquipIdList(equipIdList)
    local playerEquipmentCoreId = data.playerEquipmentCoreId
    self:SetPlayerEquipmentCoreId(playerEquipmentCoreId)
    self:InitEquipPart2SuitId()

    local isOwnEquip = false
    for i, v in ipairs(equipIdList) do
        if isOwnEquip == false then
            isOwnEquip = v > 0
            break
        end
    end

    local equipmentCoreDojo
    if playerEquipmentCoreId > 0 then
        equipmentCoreDojo = equipComp:GetEquipCoreById(playerEquipmentCoreId)
    end
    local activeCount = self:UpdateUI(equipmentCoreDojo, isOwnEquip)
    self:HandleCoreEffect(activeCount, true)
end


function UICultivateEquipAndCoreGroupNode:UpdateUI(equipmentCoreDojo, isOwnEquip, installPart)
    local oldUIState = self.uiState
    local isActive, suitId, quality = self:CheckSuitIsActive(equipmentCoreDojo)
    local uiState = isActive and UIState.Activated or (isOwnEquip and UIState.NotActive or UIState.Empty)

    self:RefreshHead(uiState, quality, suitId)
    self:RefreshCoreUI(equipmentCoreDojo, uiState)

    local activeCount = self:RefreshAllEquip(isActive, suitId, not (oldUIState == UIState.NotActive and uiState == UIState.Activated), installPart)
    self.uiState = uiState
    self.isOwnEquip = isOwnEquip
    return activeCount, suitId
end

