function UICultivateEquipAndCoreGroupNode:RefreshAllEquip(isActiveCore, suitId, isDisableEffect, installPart)
    local equipIdList = self:GetEquipIdList()
    local activeCount = 0
    for i = 1, Constants.CardEquipmentNo do
        local playerEquipId = equipIdList[i]
        ---@type EquipDojo
        local equipDojo = equipComp:GetEquipById(playerEquipId)
        local isActiveEquip = self:RefreshEquipByPart(i, equipDojo, isActiveCore, suitId, isDisableEffect, installPart)
        if isActiveEquip then
            activeCount = activeCount + 1
        end
    end
    return activeCount
end

function UICultivateEquipAndCoreGroupNode:RefreshEquipByPart(part, equipDojo, isActiveCore, suitId, isDisableEffect, installPart)
    ---@type UICultivateEquipNode
    local env = CfUtils.GetLuaScr(self.EquipNodes:GetChild(part - 1), EquipNodeEnvPath)
    if isNull(env) then return end
    env:SetIsHidePlusIcon(self.isHidePlusIcon)
    env:SetPart(part)
    env:SetCallback(Bind(self, self.OnClickEquipNodeAction))
    return env:RefreshUI(equipDojo, isActiveCore, suitId, isDisableEffect, installPart == part)
end

function UICultivateEquipAndCoreGroupNode:PlayEquipEffect(part, rare)
    ---@type UICultivateEquipNode
    local env = CfUtils.GetLuaScr(self.EquipNodes:GetChild(part - 1), EquipNodeEnvPath)
    if isNull(env) then return end
    --- 安装或替换导致的核心激活 播放所有特效
    env:PlayAllEffect(part, rare)

end

