function UICultivateEquipAndCoreGroupNode:CheckCoreActiveState(suitId, isActive, preActiveState, preActiveSuitId, installPartIsActive)
    local activeState = CoreActiveState.NotActive
    if isActive then
        --- 以前未激活 -> 激活
        if preActiveState ~= nil and preActiveState == false then
            activeState = CoreActiveState.NotActive2Active
            --- 切换套装 未激活 -> 激活
        elseif preActiveSuitId ~= nil and suitId ~= nil and preActiveSuitId ~= suitId then
            activeState = CoreActiveState.NotActive2Active
            --- 否则 如果激活 则直接播 激活 -> 激活
        elseif installPartIsActive ~= nil then
            if installPartIsActive then
                activeState = CoreActiveState.Active2Active
            end
        else
            activeState = CoreActiveState.Active2Active
        end
    end

    self.preActiveState = isActive
    self.preSuitId = suitId

    return activeState
end

