function UICultivateEquipAndCoreGroupNode:RefreshNodeByPart(part, dojo, equipmentCoreDojo)
    local isUninstall = dojo == nil
    local id = isUninstall and 0 or checkNumber(dojo.id)

    if part == -1 then
        ---------------------------------
        --- update cache data
        self:SetPlayerEquipmentCoreId(id)
        ---------------------------------
        local oldUiState = self.uiState
        local activeCount = self:UpdateUI(dojo, self.isOwnEquip)
        self:HandleCoreEffect(activeCount, not (oldUiState == UIState.NotActive and self.uiState == UIState.Activated))
    else
        local equipIdList = self:GetEquipIdList()
        equipIdList[part] = id
        local isOwnEquip = false
        for i, v in ipairs(equipIdList) do
            if isOwnEquip == false then
                isOwnEquip = v > 0
            else
                break
            end
        end

        self:UpdateEquipPart2SuitId(dojo, part)
        local equipSuitId = checkNumber(self.equipPart2SuitId[part])
        -- local isDisableActiveEffect = uiState == UIState.Activated
        local oldUiState = self.uiState
        local activeCount, coreSuitId = self:UpdateUI(equipmentCoreDojo, isOwnEquip, part)
        
        -- local isPlayCoreActiveEffect =
        --         --- 核心已激活
        --         self.uiState == UIState.Activated and
        --         --- 不是卸载装备
        --         not isUninstall and
        --         --- 安装装备与核心套装id相同
        --         (checkNumber(coreSuitId) > 0 and equipSuitId > 0 and coreSuitId == equipSuitId)


        -- self:HandleCoreEffect(activeCount, not isPlayCoreActiveEffect)
        local isPlayCoreActiveEffect = oldUiState == UIState.NotActive and self.uiState == UIState.Activated
        self:HandleCoreEffect(activeCount, not isPlayCoreActiveEffect)

        if isPlayCoreActiveEffect then
            for equipPart, suitId in pairs(self.equipPart2SuitId) do
                if suitId == coreSuitId then
                     local playerEquipId = equipIdList[checkNumber(equipPart)]
                    local equipDojo = equipComp:GetEquipById(playerEquipId)
                    local equipVo= cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
                    self:PlayEquipEffect(equipPart, equipVo.rare)
                end
            end
        end


    end
    
end

function UICultivateEquipAndCoreGroupNode:HandleCoreEffect(activeCount, isDisableActiveEffect)
    if self.uiState == UIState.Activated then
        if not isDisableActiveEffect then
            self:PlayCoreActiveEffect()
        end
        
        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_jihuo)
        self:PlayCoreLoopEffect(EffectType.Loop)
        if activeCount == Constants.CardEquipmentNo then
            -- CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_chixu)
            self:PlayCoreLoopEffect(EffectType.LoopFull)
        else
            -- CriWareUtils.Stop(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_chixu)
            self:HideCoreLoopEffect(EffectType.LoopFull)
        end
    else
        CriWareUtils.Stop(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_jihuo)
        -- CriWareUtils.Stop(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_chixu)
        self:HideCoreLoopEffect(EffectType.Loop)
        self:HideCoreLoopEffect(EffectType.LoopFull)
    end
end

function UICultivateEquipAndCoreGroupNode:StopEffectCo(effectType)
    local co = self.effectCos[effectType]
    if co then
        cs_coroutine.stop(co)
        self.effectCos[effectType] = nil
    end
end
function UICultivateEquipAndCoreGroupNode:PlayCoreActiveEffect()
    local effectType = EffectType.Active
    self:StopEffectCo(effectType)
    local co = cs_coroutine.start(function()
        local animator = self.CoreNode.gameObject:GetComponentInParent(typeof(CS.UnityEngine.Animator))
        if not isNull(animator) then
            cs_coroutine.yield_return(animator:WaitUntilAniCompleted())
        end
        local go = self.effectGos[effectType]
        if go == nil then
            if not isNull(self.CoreNode) then
                go = GameUtils.LoadBundleAsync(EffectConfig[effectType], self.CoreNode.gameObject, nil, true)
                self.effectGos[effectType] = go
            end
        else
            KTool.SetActive(go.gameObject, true)
        end
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(4))
        KTool.SetActive(go.gameObject, false)
        self.effectCos[effectType] = nil
    end)

    self.effectCos[effectType] = co
end

function UICultivateEquipAndCoreGroupNode:PlayCoreLoopEffect(effectType)
    self:StopEffectCo(effectType)
    local co = cs_coroutine.start(function()
        local animator = self.CoreNode.gameObject:GetComponentInParent(typeof(CS.UnityEngine.Animator))
        if not isNull(animator) then
            cs_coroutine.yield_return(animator:WaitUntilAniCompleted())
        end
        local go = self.effectGos[effectType]
        if go == nil then
            if not isNull(self.CoreNode) then
                go = GameUtils.LoadBundleAsync(EffectConfig[effectType], self.CoreNode.gameObject, nil, true)
                self.effectGos[effectType] = go
            end
        else
            KTool.SetActive(go.gameObject, true)
        end
        self.effectCos[effectType] = nil
    end)

    self.effectCos[effectType] = co
end

function UICultivateEquipAndCoreGroupNode:HideCoreLoopEffect(effectType)
    self:StopEffectCo(effectType)
    local go = self.effectGos[effectType]
    if go then
        KTool.SetActive(go.gameObject, false)
    end
end

